# Final manual distinctions after exact comparison, not automatic topic matching.
from collections import Counter

def revised_fate(numbers,cls,fate,refs,searches,present=None):
    for number in numbers.split():
        cid='C-SA21-'+number;c=byid[cid]
        c['class']=cls;c['fate']=fate+' Search record: '+', '.join(searches)+'.';c['refs']=refs
        if present:c['present_status']=present
        assessments[cid]={'class':cls,'search_ids':searches,'refs':refs}

